package br.com.bemdoar.service;
import br.com.bemdoar.dto.TransparenciaResponse;import br.com.bemdoar.enums.*;import br.com.bemdoar.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TransparenciaService{private final DoacaoRepository d;private final CampanhaRepository c;private final AcaoSocialRepository a;private final ParticipacaoVoluntarioRepository p;public TransparenciaService(DoacaoRepository d,CampanhaRepository c,AcaoSocialRepository a,ParticipacaoVoluntarioRepository p){this.d=d;this.c=c;this.a=a;this.p=p;}@Transactional(readOnly=true)public TransparenciaResponse obter(){return new TransparenciaResponse(d.countBySituacao(SituacaoDoacao.RECEBIDA),c.count(),a.count(),Objects0(a.somarBeneficiadosReais()),p.contarVoluntariosDistintos());}private long Objects0(Long n){return n==null?0:n;}}
